-- LearnerStreamedEventAggregateMeasure
-- An aggregated learner activity or progress measure over a digital resource and measurement
-- interval, optionally derived from a streamed event. The measure is a durable fact;
-- protocol-level collection/envelope structures are not canonical GUIDE concepts.
CREATE TABLE engagement.learner_streamed_event_aggregate_measure (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT,
    learner_streamed_event_aggregate_measure_identifier TEXT NOT NULL,
    streamed_event_digital_resource_identifier       TEXT,
    name                                             TEXT,
    description                                      TEXT,
    metric_value                                     NUMERIC NOT NULL,
    max_metric_value                                 NUMERIC,
    metric                                           TEXT NOT NULL,
    started_at_time                                  TIMESTAMP WITH TIME ZONE,
    ended_at_time                                    TIMESTAMP WITH TIME ZONE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    source_streamed_event_identifier                 TEXT,
    CONSTRAINT pk_learner_streamed_event_aggregate_measure PRIMARY KEY (tenant_identifier, learner_streamed_event_aggregate_measure_identifier)
);
COMMENT ON TABLE engagement.learner_streamed_event_aggregate_measure IS 'An aggregated learner activity or progress measure over a digital resource and measurement interval, optionally derived from a streamed event. The measure is a durable fact; protocol-level collection/envelope structures are not canonical GUIDE concepts.';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.learner_streamed_event_aggregate_measure_identifier IS 'Unique identifier for the aggregate measure';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.streamed_event_digital_resource_identifier IS 'Unique identifier for the digital resource';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.name IS 'A name for the record';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.description IS 'A description for the record';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.metric_value IS 'Observed aggregate value for the metric over the measurement interval.';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.max_metric_value IS 'Optional maximum or total possible value used to interpret the aggregate metric.';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.metric IS 'Metric represented by the aggregate value, such as minutes on task, units completed, skills mastered, or words read.';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.started_at_time IS 'Date and time at which the measurement interval began.';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.ended_at_time IS 'Date and time at which the measurement interval ended.';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.created_by IS 'Person identifier that created the record';
