COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.deleted_date IS 'Date and time record was deleted';
COMMENT ON COLUMN engagement.learner_streamed_event_aggregate_measure.source_streamed_event_identifier IS 'Optional streamed event from which this aggregate measure was derived or received.';

-- PersonRecruitmentAttribution
-- A table that stores recruitment, source, campaign, referral, UTM, event-source, territory, or
-- funnel-attribution facts associated with a person or prospective learner. This table captures
-- marketing and recruitment influence context that is broader than
-- LearnerApplication.ApplicationSourceIdentifier.
CREATE TABLE engagement.person_recruitment_attribution (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    learner_application_identifier                   TEXT,
    attribution_type_identifier                      TEXT,
    attribution_date                                 TIMESTAMP WITH TIME ZONE,
    source_name                                      TEXT,
    source_code                                      TEXT,
    source_type_identifier                           TEXT,
    source_segment                                   TEXT,
    source_index_weight                              NUMERIC,
    first_source_indicator                           BOOLEAN DEFAULT FALSE,
    calculated_indicator                             BOOLEAN DEFAULT FALSE,
    funnel_stage_identifier                          TEXT,
    territory_name                                   TEXT,
    campaign_name                                    TEXT,
    utm_source                                       TEXT,
    utm_medium                                       TEXT,
    utm_campaign                                     TEXT,
    utm_content                                      TEXT,
    event_name                                       TEXT,
    event_date                                       TIMESTAMP WITH TIME ZONE,
    source_raw_attribution_type                      TEXT,
    source_raw_source_type                           TEXT,
    source_raw_source_segment                        TEXT,
    source_raw_funnel_stage                          TEXT,
    source_raw_territory                             TEXT,
    source_raw_campaign                              TEXT,
    source_raw_event_source                          TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_recruitment_attribution PRIMARY KEY (tenant_identifier, person_identifier, sequence_number)
);
COMMENT ON TABLE engagement.person_recruitment_attribution IS 'A table that stores recruitment, source, campaign, referral, UTM, event-source, territory, or funnel-attribution facts associated with a person or prospective learner. This table captures marketing and recruitment influence context that is broader than LearnerApplication.ApplicationSourceIdentifier.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.person_identifier IS 'Tenant-scoped person/prospect identifier to whom the attribution belongs.';
