COMMENT ON COLUMN engagement.person_recruitment_attribution.attribution_type_identifier IS 'Reference-code value identifying the type of recruitment attribution.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.attribution_date IS 'Date and time associated with the source attribution.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_name IS 'Source-facing name or description of the recruitment source.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_code IS 'Source code, alias, or campaign/source code assigned by the recruitment system.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_type_identifier IS 'Reference-code value identifying the broad source type.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_segment IS 'Source segment value associated with the attribution.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_index_weight IS 'Source index or ranking weight supplied by the source system.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.first_source_indicator IS 'Indicates whether this row represents the first known recruitment source.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.calculated_indicator IS 'Indicates whether the attribution value was calculated or derived by the source system/process.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.funnel_stage_identifier IS 'Reference-code value identifying the recruitment funnel stage.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.territory_name IS 'Recruitment territory name or label associated with the person/prospect.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.campaign_name IS 'Campaign name associated with the attribution where available.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.utm_source IS 'UTM source value captured from web attribution.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.utm_medium IS 'UTM medium value captured from web attribution.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.utm_campaign IS 'UTM campaign value captured from web attribution.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.utm_content IS 'UTM content value captured from web attribution.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.event_name IS 'Event source name associated with the attribution where available.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.event_date IS 'Event and time source date associated with the attribution where available.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_raw_attribution_type IS 'Source-system attribution type value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_raw_source_type IS 'Source-system source type value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_raw_source_segment IS 'Source-system source segment value preserved as supplied.';
COMMENT ON COLUMN engagement.person_recruitment_attribution.source_raw_funnel_stage IS 'Source-system funnel stage value preserved when canonical mapping is lossy.';
